"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.31329",title:"WeVisOne-VL: Unified Visual Perception from Objects to Pixels",up:221,href:"https://arxiv.org/abs/2610.31329",abstract:"Existing vision-language models (VLMs) remain unreliable for fine-grained visual perception. In this report, we present WeVisOne-VL (WeChat Vision All-in-One), a powerful VLM that unifies object-level and pixel-level perception through structured next-token prediction. It supports multiple visual tasks including object detection, referring localization, counting, OCR, segmentation, and matting, enabling localization at any user-specific granularity, from points and boxes to masks and alpha mattes. Architecturally, we integrate a lightweight pixel decoder into the VLM via a special <OBJ> token ",pdfUrl:"https://arxiv.org/pdf/2610.31329",primaryCategory:"cs.CV",published:"2026-10-22T00:00:00Z"},{id:"2610.30926",title:"Making MLLM Latents Matter: Factor-Aware Predictive Learning for Cinematic Video Generation",up:163,href:"https://arxiv.org/abs/2610.30926",abstract:"Cinematic video generation requires both temporal inference from limited inputs (i.e., sparse rather than frame-by-frame guidance) and factor-aware control of character, scene, action, and camera. Multimodal large language models (MLLMs) offer useful priors for both capabilities, but their representations are not automatically actionable for video generation: a Video Diffusion Transformer (DiT) may bypass them through native conditioning pathways, and using them does not ensure either factor-aware control or generation-compatible temporal prediction. We propose Factor-Aware Predictive Learning",pdfUrl:"https://arxiv.org/pdf/2610.30926",primaryCategory:"cs.CV",published:"2026-10-22T08:43:48Z"},{id:"2610.30181",title:"Deep Search in Real-World Web Environments",up:149,href:"https://arxiv.org/abs/2610.30181",abstract:"Despite substantial progress in Deep Search agents, their ability to conduct end-to-end research in real-world open Web environments remains insufficiently evaluated. Unlike static retrieval settings, information on the real-world Web is distributed across diverse sources, modalities, and heterogeneous formats, often involving complex interaction mechanisms that require agents to autonomously search for, access, and integrate relevant evidence during execution. To address this gap, we introduce the OpenDS task, designed to evaluate agents' ability to perform multi-step deep search in the live,",pdfUrl:"https://arxiv.org/pdf/2610.30181",primaryCategory:"cs.IR",published:"2026-10-19T00:00:00Z"},{id:"2610.24738",title:"Editing Images into Reusable Layers via Compositional Edit-Prior Distillation",up:73,href:"https://arxiv.org/abs/2610.24738",abstract:"High-quality image editing requires precise modification of target regions while preserving the content of unrelated regions. Existing editing models produce flattened outputs that limit precise local manipulation and layer reuse, while decomposition methods typically optimize layer recovery separately from instruction-driven editing. To this end, we introduce LayerEditor, a unified framework that couples instruction-guided image editing with controllable generation of reusable RGBA layers. At its core, In-Context RGB-Alpha Token Modeling jointly represents the edited canvas and an ordered seq",pdfUrl:"https://arxiv.org/pdf/2610.24738",primaryCategory:"cs.CV",published:"2026-10-17T00:00:00Z"},{id:"2610.30949",title:"IQuest-Q1: Advancing Foundation Capabilities for Agentic CLI Systems",up:53,href:"https://arxiv.org/abs/2610.30949",abstract:"We present IQuest-Q1, a sparse Mixture-of-Experts (MoE) agentic foundation model with 320B total parameters (15B activated). IQuest-Q1 is developed through a three-stage process: (1) stable and efficient pre-training, combining Stable SplitNorm, Muon, and muP with a two-stage curriculum whose second stage increases the coding-data mixture, preserving a wide stability margin between safe and optimal learning rates; (2) fine-grained mid-training, expanding the data mixture across domains and formats and progressively extending the context; and (3) multi-scaffold with multi-version post-training,",pdfUrl:"https://arxiv.org/pdf/2610.30949",primaryCategory:"cs.CL",published:"2026-10-22T00:00:00Z"},{id:"2610.29677",title:"Toward Recursive Self-Improvement in Physical AI",up:46,href:"https://arxiv.org/abs/2610.29677",abstract:"Recursive self-improvement (RSI) describes a system that improves not only its behavior but also the process by which it improves. Recent digital agents test this idea by rewriting their own code and checking each version with executable tests. Bringing these mechanisms into the physical world requires learning from partial observations through costly trials, while accounting for changing operating conditions and potentially irreversible consequences. We position RSI within robot learning and trace pathways from improving robot capabilities to improving the processes that generate them. We exa",pdfUrl:"https://arxiv.org/pdf/2610.29677",primaryCategory:"cs.RO",published:"2026-10-21T00:00:00Z"},{id:"2610.28889",title:"Policy-Mask: Budget-Aware Adaptation of Diffusion Features to Discriminative Tasks",up:43,href:"https://arxiv.org/abs/2610.28889",abstract:"Selecting intermediate features from a frozen diffusion model for discriminative tasks is non-trivial because the useful signal is distributed across the denoising trajectory, network depth, and channels. In practice, this requires choosing a timestep, a block, and a channel subset. Existing methods either fix these choices by hand or optimize only a few extraction hyperparameters, most often the timestep, then reuse the same rule across inputs and budgets. We introduce Policy-Mask, a budget-conditioned policy trained on the downstream objective that jointly selects all three under a prescribe",pdfUrl:"https://arxiv.org/pdf/2610.28889",primaryCategory:"cs.CV",published:"2026-10-20T00:00:00Z"},{id:"2610.25100",title:"Deep Fusion Memory: A Chunk-Level Parametric Memory for Large Language Models",up:39,href:"https://arxiv.org/abs/2610.25100",abstract:"Large language models need effective ways to acquire and use external knowledge beyond what they retain from pretraining. Continued pretraining risks catastrophic forgetting, while retrieval at inference time can add substantial overhead. External parametric memory avoids online retrieval, but constructing its training data requires extensive offline search, and output-level interpolation provides only shallow fusion. We introduce Deep Fusion Memory (DFM), a parametric memory architecture that reduces this construction workload and incorporates learned memory into intermediate hidden states. A",pdfUrl:"https://arxiv.org/pdf/2610.25100",primaryCategory:"cs.CL",published:"2026-10-18T00:00:00Z"},{id:"2610.23987",title:"What Generation Knows: Unlocking Fine-Grained Understanding in Unified Multimodal Models",up:32,href:"https://arxiv.org/abs/2610.23987",abstract:"Fine-grained visual understanding requires distinguishing subtle differences in local attributes and spatial relations, yet remains challenging for existing vision-language models. Unified multimodal models (UMMs) offer a new opportunity through generation pathways that preserve rich visual information complementary to understanding. However, existing generation-assisted understanding methods mainly rely on generative supervision or explicit generation and have not systematically explored direct use of native generation-side representations. To address this gap, we systematically analyze what ",pdfUrl:"https://arxiv.org/pdf/2610.23987",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.27851",title:"LaLa-World: Scaling Latent World Models with Natural Language Actions",up:27,href:"https://arxiv.org/abs/2610.27851",abstract:"This paper shows that JEPA-style latent world models (LWMs) can learn across diverse domains and data sources by adopting the language-conditioned interface of video generation models. We establish this approach as an effective and efficient basis for planning with imagination and downstream policy fine-tuning. To this end, we introduce LaLa-World, a Language-conditioned Latent World model that learns from simulation and robot trajectories together with broader image and video data. Two designs make this work. First, we describe both numerical actions and visual changes in language, enabling j",pdfUrl:"https://arxiv.org/pdf/2610.27851",primaryCategory:"cs.CV",published:"2026-10-21T00:00:00Z"},{id:"2610.27598",title:"Meta Expert: Cross-Layer Expert Sharing for Storage- and Retrieval-Efficient MoE",up:25,href:"https://arxiv.org/abs/2610.27598",abstract:"As model parameters scale up, sparsely activated Mixture-of-Experts (MoE) approaches have become essential for model scaling. However, mainstream models currently adopt hierarchical architectures, where experts in different layers, although topologically independent, exhibit substantial similarity and redundancy in their stored content. Compared to the hierarchically arranged \\textbf{Local Expert} in existing mainstream models, we hypothesize that inter-layer shared \\textbf{Meta Expert} hold greater potential. To this end, we conduct a multi-dimensional empirical comparison between Local and M",pdfUrl:"https://arxiv.org/pdf/2610.27598",primaryCategory:"cs.AI",published:"2026-10-20T00:00:00Z"},{id:"2610.28416",title:"Code2Video-Compass: A Comprehensive Benchmark for General-Purpose Code-Based Video Generation across T2V, I2V, and V2V",up:24,href:"https://arxiv.org/abs/2610.28416",abstract:"Code-based video generation offers fine-grained control, targeted editing, and component reuse compared with direct video generation. This approach requires multimodal large language models (MLLMs) to translate visual and temporal requirements into executable programs that produce complete videos. However, existing code-based benchmarks primarily target specialized tasks, leaving complete video creation across diverse creative categories and input modalities insufficiently evaluated. We introduce Code2Video-Compass, a general-purpose benchmark for code-based video generation across text-to-vid",pdfUrl:"https://arxiv.org/pdf/2610.28416",primaryCategory:"cs.CV",published:"2026-10-20T00:00:00Z"},{id:"2610.30320",title:"Self-Distilling Future Video Representations for World Action Models",up:23,href:"https://arxiv.org/abs/2610.30320",abstract:"World Action Models (WAMs) have emerged as a promising approach to learning generalist robot policies using rich spatiotemporal priors from pre-trained video diffusion models. A recent line of WAMs improves inference efficiency by conditioning a separate action decoder on intermediate future video representations extracted from a single denoising step, avoiding costly iterative denoising required for video generation. This design makes action prediction depend directly on the quality of these future representations. In this paper, we introduce Future REpresentation learning via self-Distillati",pdfUrl:"https://arxiv.org/pdf/2610.30320",primaryCategory:"cs.RO",published:"2026-10-21T00:00:00Z"},{id:"2610.26233",title:"Heartbeat Thinking: Speculative Reasoning and Tool Execution While Listening in Realtime Voice Agents",up:18,href:"https://arxiv.org/abs/2610.26233",abstract:"Tool-using voice agents often leave users waiting after speech ends, even when actionable information arrives earlier in the request. Speculative approaches begin work during speech, but chunk-bounded or interrupt-on-update generation can truncate a tool call before its arguments are complete. This couples computation time to speech updates, limiting useful work completed in advance. We introduce Heartbeat Thinking, which handles updated input through new Thinker invocations while allowing ongoing invocations and dispatched tools to finish. Periodic invocations read the latest partial transcri",pdfUrl:"https://arxiv.org/pdf/2610.26233",primaryCategory:"cs.CL",published:"2026-10-19T00:00:00Z"},{id:"2610.19705",title:"RouteWeaver: Weaving Mode Selection and Execution into Unified LLM Routing",up:17,href:"https://arxiv.org/abs/2610.19705",abstract:"LLM routing dynamically selects and coordinates heterogeneous language models across diverse tasks. However, existing approaches are largely built around a predefined execution paradigm, such as single-round, multi-round, or agentic routing, which fixes how model calls are organized and limits adaptation to different query needs. We propose RouteWeaver, a unified routing framework that integrates these routing modes within a single LLM policy, jointly learning which mode to use and how to select models within that mode. To jointly optimize mode selection and within-mode execution, we develop C",pdfUrl:"https://arxiv.org/pdf/2610.19705",primaryCategory:"cs.CL",published:"2026-10-19T00:00:00Z"},{id:"2610.31158",title:"Beyond Watching and Searching: Benchmarking Agents for Video-centered Deep Research Reports",up:17,href:"https://arxiv.org/abs/2610.31158",abstract:"Deep research agents synthesize open-web evidence into long reports, but current benchmarks do not evaluate research centered on a source video. We introduce Video-Centered Deep Research Report Generation. Given a video and user request, an agent identifies research questions, retrieves external multimodal evidence, and produces an interactive report linked to relevant video moments. This task has direct practical value because it helps users locate relevant moments, verify claims, reproduce demonstrated procedures, and make informed decisions from video content. We present a skill-based workf",pdfUrl:"https://arxiv.org/pdf/2610.31158",primaryCategory:"cs.CV",published:"2026-10-22T00:00:00Z"},{id:"2610.27712",title:"RLSplat: Resource-Linear Budget Control for Feed-forward 3D Gaussian Splatting",up:15,href:"https://arxiv.org/abs/2610.27712",abstract:"Feed-forward 3D Gaussian Splatting (FF3DGS) reconstructs 3D scenes from images in a single forward pass, making it well-suited to applications that must operate within limited resource budgets. To further improve its practicality, recent budget-controllable FF3DGS methods allow the number of Gaussians to be adjusted at inference, so that the output meets a given storage limit or rendering-latency constraint. However, these methods overlook the cost of inference itself: to produce a representation with the target number of Gaussians, they first predict a dense set of Gaussians and then prune or",pdfUrl:"https://arxiv.org/pdf/2610.27712",primaryCategory:"cs.CV",published:"2026-10-20T00:00:00Z"},{id:"2610.30755",title:"Is Complex Agentic Memory Always Needed? Naive RAG Is Stronger Than We Thought",up:15,href:"https://arxiv.org/abs/2610.30755",abstract:"LLM memory is widely used in long-term conversation understanding. Agentic memory systems often use mutation, structural organization, learned retrieval strategies, or other complex operations. Is this complexity always necessary? We study Raw-RAG, a naive RAG baseline using dense retrieval and reranking over raw history to supply evidence to a reader LLM. Across LoCoMo, LongMemEval, MEME, and MemoryAgentBench, Raw-RAG ranks first among the compared memory systems in six of seven benchmark-model settings, outperforming the strongest compared agentic memory system by 0.13-5.53 points. We invest",pdfUrl:"https://arxiv.org/pdf/2610.30755",primaryCategory:"cs.AI",published:"2026-10-22T00:00:00Z"},{id:"2610.31305",title:"Cola2: Co-Adaptive Hierarchical Language Modeling with Continuous Semantic Compression and Balanced Discrete Generation",up:14,href:"https://arxiv.org/abs/2610.31305",abstract:"Hierarchical language generation separates continuous semantic modeling from discrete text realization, but its effectiveness depends on what the latent space compresses and how the discrete generator uses it. We propose Cola2, a framework that jointly studies continuous semantic compression, the balance between reconstruction and generation, and continuous-discrete co-adaptation. Cola2 dynamically segments text into semantic spans, controls the compression rate through auxiliary-loss-free negative feedback, and combines reconstruction and generation supervision to learn compact, predictive la",pdfUrl:"https://arxiv.org/pdf/2610.31305",primaryCategory:"cs.CL",published:"2026-10-22T00:00:00Z"},{id:"2610.20091",title:"RTAformer: Relation-Transition-Aware Transformer for Video Scene Graph Generation",up:12,href:"https://arxiv.org/abs/2610.20091",abstract:"Video scene graph generation (VidSGG) aims to capture objects and their evolving relationships in videos. This requires accounting for both the persistence of object identities and abrupt changes in relationships. Existing methods aggregate information across frames to exploit temporal context, but an emphasis on consistency can obscure these changes. As a result, a model may retain its previous prediction even after the underlying relation has changed. We refer to this failure mode as relational semantic inertia. To address this issue, we propose Relation-Transition-Aware Transformer (RTAform",pdfUrl:"https://arxiv.org/pdf/2610.20091",primaryCategory:"cs.CV",published:"2026-10-14T00:00:00Z"},{id:"2610.30753",title:"FilmFlow: Agentic System for 3D Virtual Film Cinematography",up:12,href:"https://arxiv.org/abs/2610.30753",abstract:"Complex camera motion is central to visual storytelling, yet translating cinematographic intent into controllable, executable camera trajectories remains challenging. We introduce FilmFlow, an agentic framework that converts natural-language instructions or reference videos into explicit camera trajectories for dynamic 3D environments. To generate these trajectories, a Director agent constructs executable camera plans by composing high-level motions from concurrent atomic operations that jointly control translation, rotation, and framing. The Director is supported by three specialized agents: ",pdfUrl:"https://arxiv.org/pdf/2610.30753",primaryCategory:"cs.CV",published:"2026-10-22T00:00:00Z"},{id:"2610.30866",title:"Verus-Insight: Towards Explainable Artifact Detection in AI-Generated Videos",up:12,href:"https://arxiv.org/abs/2610.30866",abstract:"Recent advances in video generation have made synthetic videos increasingly realistic, placing greater demands on reliable AI-generated video detection. Existing artifact-based detectors typically identify generation artifacts as evidence for source prediction, yet they may either fail to recognize subtle artifacts or reach the correct source decision without faithfully identifying the evidence underlying it. In this work, we systematically investigate how to design and train effective artifact detectors and formulate artifact detection as a structured process comprising three complementary ca",pdfUrl:"https://arxiv.org/pdf/2610.30866",primaryCategory:"cs.CV",published:"2026-10-22T00:00:00Z"},{id:"2610.31574",title:"Rethinking Sequence Compression with Test-time Regression",up:12,href:"https://arxiv.org/abs/2610.31574",abstract:"Sequence compression is a fundamental operation and a critical information bottleneck in efficient language and multimodal models, and yet prevailing approaches based on pooling or learned projections remain underperforming. We revisit sequence compression through the lens of test-time regression: input tokens define a regression problem whose fitted coefficients form the compressed representation. Importantly, the regression problem is learned end-to-end via backpropagation, while its coefficients are computed efficiently in closed form during the forward pass. This leads to TTR-Compressor, a",pdfUrl:"https://arxiv.org/pdf/2610.31574",primaryCategory:"cs.LG",published:"2026-10-22T17:14:38Z"},{id:"2610.30418",title:"Agent Mosaic: Recognizing Confidentiality Leaks in Agentic LLM Systems",up:11,href:"https://arxiv.org/abs/2610.30418",abstract:"Modern LLM agents can retrieve information from accessible documents, and then disclose a sensitive conclusion assembled from them. This mosaic effect creates a critical risk for agents operating over confidential data. We quantify its realization with 30 synthetic cybersecurity, medical, and military examples, yielding 10,800 final answers from three LLM agents in controlled simulation and 1,440 answers from live agents in two open-source harnesses. Even under benign queries designed to be answerable from one document, GPT-5.6-Sol, the best performing model tested, discloses forbidden composi",pdfUrl:"https://arxiv.org/pdf/2610.30418",primaryCategory:"cs.CR",published:"2026-10-21T00:00:00Z"},{id:"W4393160747",title:"ExpeL: LLM Agents Are Experiential Learners",up:0,href:"https://doi.org/10.1609/aaai.v38i17.29936",doi:"https://doi.org/10.1609/aaai.v38i17.29936",year:2024,openalexId:"https://openalex.org/W4393160747"},{id:"W4412877164",title:"Evaluation and Benchmarking of LLM Agents: A Survey",up:0,href:"https://doi.org/10.1145/3711896.3736570",crossrefDoi:"https://doi.org/10.1145/3711896.3736570",year:2025,openalexId:"https://openalex.org/W4412877164",crossrefIssued:"2025-08-03"},{id:"W4407759090",title:"A-Mem: Agentic Memory for LLM Agents",up:0,href:"https://doi.org/10.52202/085713-0593",doi:"https://doi.org/10.52202/085713-0593",year:2025,openalexId:"https://openalex.org/W4407759090"}]}}]);